/**
 * A base interface for implementations of {@link TraceCodeUnit}
 * 
 * <p>
 * This behaves somewhat like a mixin, allowing it to be used on code units as well as data
 * components, e.g., fields of a struct data unit.
 */
public interface DBTraceCodeUnitAdapter : TraceCodeUnit, MemBufferMixin {

	/* @Override */
	DBTrace getTrace();

	/* @Override */
	TraceProgramView getProgram() {
		return getTrace().getProgramView();
	}

	// TODO: Do I delete comments when code unit is deleted?
	// TODO: Do I adjust lifespan of comments with code unit?
	// TODO: Same two questions for properties
	// I'm leaning toward "no" on all

	/* @Override */
	string getAddressString(bool showBlockName, bool pad) {
		using (LockHold hold = LockHold.@lock(getTrace().getReadWriteLock().readLock()))
{
			Address address = getAddress();
			if (!showBlockName) {
				return address.toString(false, pad);
			}
			TraceMemoryRegion region =
				getTrace().getMemoryManager().getRegionContaining(getStartSnap(), address);
			if (region == null) {
				return address.toString(showBlockName, pad);
			}
			return region.getName(getStartSnap()) + ":" + address.toString(false, pad);
		}
	}

	AddressSpace getAddressSpace() {
		return getAddress().getAddressSpace();
	}

	/* @Override */
	void setProperty<T>(string name, Class<T> valueClass, T value) {
		using (LockHold hold = LockHold.@lock(getTrace().getReadWriteLock().writeLock()))
{
			TracePropertyMap<T> map = getTrace().getInternalAddressPropertyManager()
					.getOrCreatePropertyMapSuper(name, valueClass);
			TracePropertyMapSpace<T> space =
				map.getPropertyMapSpace(getAddressSpace(), true);
			space.set(getLifespan(), getAddress(), value);
		}
	}

	/* @Override */
	void setTypedProperty<T, U>/* where U : T */(string name, T value) {
		/* @SuppressWarnings("unchecked") */
		Class<U> valueClass = (Class<U>) value.GetType();
		setProperty(name, valueClass, valueClass.cast(value));
	}

	/* @Override */
	void setProperty(string name, Saveable value) {
		setTypedProperty(name, value);
	}

	/* @Override */
	void setProperty(string name, string value) {
		setProperty(name, typeof(string), value);
	}

	/* @Override */
	void setProperty(string name, int value) {
		setProperty(name, typeof(Integer), value);
	}

	/* @Override */
	void setProperty(string name) {
		setProperty(name, typeof(Void), null);
	}

	/* @Override */
	T getProperty<T>(string name, Class<T> valueClass) {
		using (LockHold hold = LockHold.@lock(getTrace().getReadWriteLock().readLock()))
{
			TracePropertyMap<T> map = getTrace().getInternalAddressPropertyManager()
					.getPropertyMapExtends(name, valueClass);
			if (map == null) {
				return null;
			}
			TracePropertyMapSpace<T> space =
				map.getPropertyMapSpace(getAddressSpace(), false);
			if (space == null) {
				return null;
			}
			return space.get(getStartSnap(), getAddress());
		}
	}

	/* @Override */
	Saveable getObjectProperty(string name) {
		return getProperty(name, typeof(Saveable));
	}

	/* @Override */
	string getStringProperty(string name) {
		return getProperty(name, typeof(string));
	}

	/* @Override */
	int getIntProperty(string name)
    {
		Integer value = getProperty(name, typeof(Integer));
		if (value == null) {
			throw new NoValueException();
		}
		return value;
	}

	/* @Override */
	bool hasProperty(string name) {
		using (LockHold hold = LockHold.@lock(getTrace().getReadWriteLock().readLock()))
{
			TracePropertyMapOperations<object> map =
				getTrace().getInternalAddressPropertyManager().getPropertyMap(name);
			if (map == null) {
				return false;
			}
			// NOTE: Properties all defined at start snap
			return map.getAddressSetView(Lifespan.at(getStartSnap())).contains(getAddress());
		}
	}

	/* @Override */
	bool getVoidProperty(string name) {
		// NOTE: Nearly identical to hasProperty, except named property must be Void type
		// NOTE: No need to use Extends. Nothing extends Void.
		using (LockHold hold = LockHold.@lock(getTrace().getReadWriteLock().readLock()))
{
			TracePropertyMap<Void> map =
				getTrace().getInternalAddressPropertyManager().getPropertyMap(name, typeof(Void));
			if (map == null) {
				return false;
			}
			TracePropertyMapSpace<Void> space = map.getPropertyMapSpace(getAddressSpace(), false);
			if (space == null) {
				return false;
			}
			return map.getAddressSetView(Lifespan.at(getStartSnap())).contains(getAddress());
		}
	}

	/* @Override */
	Iterator<string> propertyNames() {
		Lifespan span = Lifespan.at(getStartSnap());
		return IteratorUtils.transformedIterator(IteratorUtils.filteredIterator(
			getTrace().getInternalAddressPropertyManager().getAllProperties().entrySet().iterator(),
			e => e.getValue().getAddressSetView(span).contains(getAddress())), Entry.getKey);
	}

	/* @Override */
	void removeProperty(string name) {
		using (LockHold hold = LockHold.@lock(getTrace().getReadWriteLock().writeLock()))
{
			TracePropertyMapOperations<object> map =
				getTrace().getInternalAddressPropertyManager().getPropertyMap(name);
			if (map == null) {
				return;
			}
			map.clear(getLifespan(), new AddressRangeImpl(getMinAddress(), getMaxAddress()));
		}
	}

	/* @Override */
	string getLabel() {
		using (LockHold hold = getTrace().lockRead())
{
			Symbol primary = getPrimarySymbol();
			return primary == null ? null : primary.getName();
		}
	}

	/* @Override */
	default Symbol[] getSymbols() {
		using (LockHold hold = getTrace().lockRead())
{
			Collection<TraceSymbol> at =
				getTrace().getSymbolManager().labels().getAt(getStartSnap(), getAddress(), true);
			return at.toArray(new TraceSymbol[at.size()]);
		}
	}

	/* @Override */
	Symbol getPrimarySymbol() {
		using (LockHold hold = getTrace().lockRead())
{
			Collection<TraceSymbol> at =
				getTrace().getSymbolManager().labels().getAt(getStartSnap(), getAddress(), true);
			if (at.isEmpty()) {
				return null;
			}
			return at.iterator().next();
		}
	}

	/* @Override */
	Address getMinAddress() {
		return getAddress();
	}

