		return getTrace().getCommentAdapter().getComment(getStartSnap(), getAddress(), commentType);
	}

	/* @Override */
	void setCommentAsArray(CommentType commentType, string[] comment) {
		setComment(commentType, DBTraceCommentAdapter.commentFromArray(comment));
	}

	/* @Override */
	default string[] getCommentAsArray(CommentType commentType) {
		return DBTraceCommentAdapter.arrayFromComment(getComment(commentType));
	}

	/* @Override */
	bool contains(Address testAddr) {
		return getMinAddress().compareTo(testAddr) <= 0 && testAddr.compareTo(getMaxAddress()) <= 0;
	}

	/* @Override */
	int compareTo(Address addr) {
		if (addr.compareTo(this.getMinAddress()) < 0) {
			return -1;
		}
		if (addr.compareTo(this.getMaxAddress()) > 0) {
			return 1;
		}
		return 0;
	}

	/* @Override */
	void addMnemonicReference(Address refAddr, RefType refType, SourceType sourceType) {
		getTrace().getReferenceManager()
				.addMemoryReference(getLifespan(), getAddress(), refAddr, refType, sourceType,
					MNEMONIC);
	}

	/* @Override */
	void addOperandReference(int index, Address refAddr, RefType type,
			SourceType sourceType) {
