				.addMemoryReference(getLifespan(), getAddress(), refAddr, type, sourceType, index);
	}

	/* @Override */
	void setPrimaryMemoryReference(Reference @ref) {
		DBTraceReference dbRef = getTrace().getReferenceManager().assertIsMine(@ref);
		dbRef.setPrimary(true);
	}

	/* @Override */
	void setStackReference(int opIndex, int offset, SourceType sourceType,
			RefType refType) {
		getTrace().getReferenceManager()
				.addStackReference(getLifespan(), getAddress(), offset, refType, sourceType,
					opIndex);
	}

	/* @Override */
	void setRegisterReference(int opIndex, Register reg, SourceType sourceType,
			RefType refType) {
		getTrace().getReferenceManager()
				.addRegisterReference(getLifespan(), getAddress(), reg, refType, sourceType,
					opIndex);
	}

	/* @Override */
	default DBTraceReference[] getMnemonicReferences() {
		return getOperandReferences(CodeUnit.MNEMONIC);
	}

	/* @Override */
	default DBTraceReference[] getOperandReferences(int index) {
		Collection<TraceReference> refs =
			getTrace().getReferenceManager().getReferencesFrom(getStartSnap(), getAddress(), index);
		return refs.toArray(new DBTraceReference[refs.size()]);
	}

	/* @Override */
	DBTraceReference getPrimaryReference(int index) {
		return getTrace().getReferenceManager()
				.getPrimaryReferenceFrom(getStartSnap(), getAddress(), index);
	}

